CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.admin_access_emails (email text PRIMARY KEY);
GRANT ALL ON public.admin_access_emails TO service_role;
ALTER TABLE public.admin_access_emails ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assign_import_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.admin_access_emails WHERE email=lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_import_admin() FROM PUBLIC;
CREATE TRIGGER assign_import_admin AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_import_admin();
CREATE TABLE public.partner_catalog (object_id text PRIMARY KEY, source text NOT NULL, record jsonb NOT NULL, last_synced_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.partner_catalog TO anon, authenticated;
GRANT ALL ON public.partner_catalog TO service_role;
ALTER TABLE public.partner_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_catalog_read ON public.partner_catalog FOR SELECT TO anon,authenticated USING (record->>'status'='active');
CREATE INDEX partner_catalog_source_idx ON public.partner_catalog(source);
CREATE TABLE public.catalog_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL DEFAULT 'awin', status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed')), github_run_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error text);
GRANT SELECT ON public.catalog_imports TO authenticated;
GRANT ALL ON public.catalog_imports TO service_role;
ALTER TABLE public.catalog_imports ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_import_read ON public.catalog_imports FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'));
CREATE TABLE public.catalog_import_batches (import_id uuid NOT NULL REFERENCES public.catalog_imports(id), batch integer NOT NULL, indexed integer NOT NULL DEFAULT 0, skipped integer NOT NULL DEFAULT 0, PRIMARY KEY(import_id,batch));
GRANT SELECT ON public.catalog_import_batches TO authenticated;
GRANT ALL ON public.catalog_import_batches TO service_role;
ALTER TABLE public.catalog_import_batches ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_batch_read ON public.catalog_import_batches FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin'));
CREATE UNIQUE INDEX single_active_awin_import ON public.catalog_imports(source) WHERE status IN ('queued','running');